#!/usr/bin/env bash
# Question 12: API resources and Roles. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/api-resources
mkdir -p /opt/course/api-resources
chown -R ubuntu:ubuntu /opt/course
counts=($(shuf -e 2 4 7))
i=0
for team in red blue green; do
  ns="${Q12_NS}-$team"
  kubectl create namespace "$ns" >/dev/null 2>&1 || kubectl get namespace "$ns" >/dev/null
  kubectl -n "$ns" delete role --all >/dev/null
  for n in $(seq 1 "${counts[$i]}"); do
    kubectl -n "$ns" create role "reader-$n" --verb=get,list --resource=pods >/dev/null
  done
  i=$((i + 1))
done
: "${Q12_NS}"
